{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Whether repeated testing occurred is unknown."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish variation across repeated runs."
        }
      ],
      "instrument_review": "MESA 14: Not sure; repeated testing is unspecified. MESA 16: cross-run stability is not established by the single reported score."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Without repeated runs, stability remains unknown; this does not demonstrate instability."
        }
      ],
      "instrument_review": "MESA 14: No; the developers explicitly did not repeat the evaluation. MESA 16: the reported findings do not establish cross-run stability."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated testing under the same conditions is explicitly reported."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's definition of stable: at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes; repeated testing occurred. For MESA 16, the observed range supports stability under the stated definition for this comparison."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated testing under the same conditions is explicitly reported."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability limit of two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes; testing occurred despite unfavourable stability findings. For MESA 16, the reported range contradicts stability under the report's definition."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "The installation instructions supply no evidence of repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added documentation provides no findings about cross-run variation."
        }
      ],
      "instrument_review": "MESA 14: Not sure; repeated testing remains unspecified. Installation guidance is relevant to MESA 22 reproducibility documentation, but does not establish score stability."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A performed better on the evaluated grid puzzles under the described conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings do not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 2 and 25: the intended comparison stays within the evaluated grid puzzles. MESA 20: broader performance is not established by these findings."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results support A's better performance on these grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Declaring a broad intended use does not supply evidence of greater general intelligence."
        }
      ],
      "instrument_review": "MESA 2: the intended use is stated. MESA 9 and 20: evidence for cross-domain coverage and generalization is insufficient, so the intended selection cannot be justified from these results alone."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The passage supplies no initial evidence linking those scores to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied workshop; the reported difference interval is positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not establish an unmeasured safety benefit."
        }
      ],
      "instrument_review": "MESA 20: the later trial supplies evidence for decision correctness beyond initial test scores in the studied setting. MESA 16: the difference interval supports that comparison. MESA 25: conclusions should remain limited to correctness in this workshop; safety benefits remain unknown."
    }
  ],
  "closing_note": "No instructions required clarification. Probe labels classify statements, while MESA judgments distinguish whether testing occurred from whether its findings were favourable. No aggregate score was calculated."
}
